def split_words(txt):
    if ',' in txt:
        return txt.split(',')
    else:
        return [txt]

# Test cases
print(split_words("Hello dunia!"))  # Output: ["Hello", "!"]
print(split_words("Hello,world!"))  # Output: ["Hello", "world!"]
print(split_words("abellocdef"))  # Output: ["abellocdef"]
```

